function (vars) {
	var g = new GridWidget(vars.element, vars.references);
	g.editable = false;
	g.sortable = false;
	g.filterable = false;
	g.pageable = false;
	g.scrollable = false;
	g.groupable = false;
	g.columns = [
		{ field: "SystemId", type: "string", title: "[resource_shortdisplayname[SystemId]]", width: 100 },
		{ field: "Value", type: "string", title: "[resource_shortdisplayname[ReferenceValue]]" }
	];
	vars.ReferenceGrid = g;
	return g;
}
